-- Generated by scripts/build-java-seed.mjs. NOT a migration: this folder is outside
-- supabase/migrations, so the CLI never applies it. Run it by hand, once, in one transaction.
--
-- Puts the 20 lesson bodies and short_descriptions back to the original
-- 0047_seed_java_tutorial_content.sql text, but only where they still hold this batch's text (a later admin edit
-- is left alone and reported). Removes the 20 Practice Problems blocks this batch added and the
-- 20 mock tests with their MCQs. Deleting a mock test also deletes students' attempts on it;
-- the count is printed first. Topics, bookmarks and progress are never touched.
-- Safe to run twice: the second run finds nothing and changes nothing.
-- ----------------------------------------------------------------------------
do $rollback$
declare
  v_attempts int; v_n int;
begin
  select count(*) into v_attempts from public.test_attempts where test_id in ('pt-java-linkedlist', 'pt-java-hashset', 'pt-java-treemap', 'pt-java-treeset', 'pt-java-iterator', 'pt-java-comparable', 'pt-java-comparator', 'pt-java-generics', 'pt-java-wrapper-classes', 'pt-java-enum', 'pt-java-access-modifiers', 'pt-java-encapsulation', 'pt-java-final-keyword', 'pt-java-super-keyword', 'pt-java-stringbuilder', 'pt-java-string-pool', 'pt-java-synchronization', 'pt-java-executor-framework', 'pt-java-garbage-collection', 'pt-java-jdbc');
  raise notice 'rollback: removing 20 mock test(s) if present; this deletes % test attempt(s).', v_attempts;
  delete from public.practice_tests where id in ('pt-java-linkedlist', 'pt-java-hashset', 'pt-java-treemap', 'pt-java-treeset', 'pt-java-iterator', 'pt-java-comparable', 'pt-java-comparator', 'pt-java-generics', 'pt-java-wrapper-classes', 'pt-java-enum', 'pt-java-access-modifiers', 'pt-java-encapsulation', 'pt-java-final-keyword', 'pt-java-super-keyword', 'pt-java-stringbuilder', 'pt-java-string-pool', 'pt-java-synchronization', 'pt-java-executor-framework', 'pt-java-garbage-collection', 'pt-java-jdbc');   -- cascades test_questions, test_attempts
  delete from public.learning_contents c using public.learning_topics t
   where t.id = c.topic_id and t.source_kind = 'java_tutorial' and t.source_ref in ('collections-framework/linkedlist', 'collections-framework/hashset', 'collections-framework/treemap', 'collections-framework/treeset', 'collections-framework/iterator', 'collections-framework/comparable', 'collections-framework/comparator', 'advanced-java/generics', 'advanced-java/wrapper-classes', 'advanced-java/enum', 'object-oriented-programming/access-modifiers', 'object-oriented-programming/encapsulation', 'object-oriented-programming/final-keyword', 'object-oriented-programming/super-keyword', 'arrays-and-strings/stringbuilder', 'arrays-and-strings/string-pool', 'multithreading/synchronization', 'multithreading/executor-framework', 'jvm-internals-and-memory/garbage-collection', 'file-handling-and-jdbc/jdbc')
     and c.metadata ->> 'source' = 'java_practice_seed' and c.metadata ->> 'origin' = 'java_lesson_rewrite';
  get diagnostics v_n = row_count;
  raise notice 'rollback: removed % practice block(s).', v_n;
end
